import math

def lr_at(step, base_lr, warmup, total):
    if warmup > 0 and step < warmup:
        return base_lr * (step / warmup)
    if step == 0 and warmup == 0:
        return base_lr * 0.5 * (1 + math.cos(0.0))  # = base_lr
    if warmup == 0:
        if step >= total:
            return base_lr * 0.5 * (1 + math.cos(math.pi))  # 0.0
        return base_lr * 0.5 * (1 + math.cos(math.pi * step / total))
    if step >= total:
        return base_lr * 0.5 * (1 + math.cos(math.pi))  # 0.0
    return base_lr * 0.5 * (1 + math.cos(math.pi * (step - warmup) / (total - warmup)))
