import math

def lr_at(step, base_lr, warmup, total):
    if step < 0:
        raise ValueError("step must be non-negative")
    if total <= 0:
        raise ValueError("total must be positive")
    if warmup < 0 or warmup > total:
        raise ValueError("warmup must satisfy 0 <= warmup <= total")

    if warmup > 0 and step < warmup:
        # Linear warmup; handles step=0 (returns 0 * base_lr)
        return base_lr * (step / warmup)

    # Cosine decay phase (also covers warmup=0 entirely)
    decay_steps = total - warmup
    if decay_steps == 0:
        # No decay phase: stay at base_lr through warmup
        return base_lr

    progress = (step - warmup) / decay_steps
    if progress > 1.0:
        progress = 1.0  # clamp beyond total
    return base_lr * 0.5 * (1.0 + math.cos(math.pi * progress))
