def train_bpe(corpus, n):
    seq = list(corpus)
    merges = []

    for _ in range(n):
        counts = {}
        for i in range(len(seq) - 1):
            pair = (seq[i], seq[i + 1])
            counts[pair] = counts.get(pair, 0) + 1

        if not counts:
            break

        best_pair = None
        best_count = 0
        for pair, count in counts.items():
            if count > best_count:
                best_pair = pair
                best_count = count

        if best_count < 2:
            break

        merges.append(best_pair)

        a, b = best_pair
        merged = []
        i = 0
        while i < len(seq):
            if i + 1 < len(seq) and seq[i] == a and seq[i + 1] == b:
                merged.append((a, b))
                i += 2
            else:
                merged.append(seq[i])
                i += 1
        seq = merged

    return merges
