def topo_sort(nodes, edges):
    """Return a topological ordering of a DAG.

    nodes: iterable of node ids
    edges: iterable of (from, to) pairs
    Raises ValueError if the graph contains a cycle.
    """
    adj = {n: [] for n in nodes}
    indegree = {n: 0 for n in nodes}

    for u, v in edges:
        if u not in adj or v not in adj:
            raise ValueError(f"Edge references unknown node: {u!r} -> {v!r}")
        adj[u].append(v)
        indegree[v] += 1

    # Kahn's algorithm with DFS-based cycle detection alternative:
    # use a stack of zero-indegree nodes
    stack = [n for n in nodes if indegree[n] == 0]
    order = []

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                stack.append(v)

    if len(order) != len(indegree):
        raise ValueError("Graph contains a cycle")

    return order
```

