def next_scale(grad_norms, initial_scale):
    scale = float(initial_scale)
    results = []
    for g in grad_norms:
        if g is None or math.isinf(g) or math.isnan(g):
            skip = True
        else:
            skip = False
        results.append((skip, scale))
        if skip:
            scale = max(scale / 2.0, 1.0)
        else:
            scale = scale * 2.0
    return results
